 {banners.length>1&&<div className="hero-banner-dots" role="group" aria-label="Banner navigation">{banners.map((item,index)=><button key={item._id||item.id||index} type="button" className={index===activeBanner?'active':''} aria-label={`Show banner ${index+1} of ${banners.length}`} aria-current={index===activeBanner?'true':undefined} onClick={()=>changeBanner(index,index>=activeBanner?1:-1)}/>)}</div>}
