    <div className="detail-price-row"><div className="detail-price">{money(p.price)} {p.oldPrice>0&&<del>{money(p.oldPrice)}</del>}</div>{discountPercent>0&&<span className="detail-discount-pill">-{discountPercent}%</span>}<span className="detail-size-prompt-price">সাইজ নির্বাচন করুন</span><div className="size-options detail-size-options-inline">{(availableSizes.length?availableSizes:['S','M','L']).map(s=>{const available=variantRows.length?variantRows.some(v=>String(v.size||'').toLowerCase()===String(s).toLowerCase()&&(!color||String(v.color||'').toLowerCase()===String(color).toLowerCase())&&Number(v.stock)>0):Number(p.stock??0)>0;return <button type="button" className={size===s?'selected':''} aria-pressed={size===s} disabled={!available} onClick={()=>{setSize(s);setQty(1)}} key={s}>{s}</button>})}</div>{availableColors.length>0&&<div className="detail-inline-color-select"><span className="detail-size-prompt-price">রং</span><div className="color-options detail-color-options-inline">{availableColors.map(c=>{const available=variantRows.length?variantRows.some(v=>String(v.color||'').toLowerCase()===String(c).toLowerCase()&&(!size||String(v.size||'').toLowerCase()===String(size).toLowerCase())&&Number(v.stock)>0):Number(p.stock??0)>0;return <button type="button" className={color===c?"selected":""} aria-pressed={color===c} aria-label={c+(available?'':' — out of stock')} title={c+(available?'':' — out of stock')} disabled={!available} onClick={()=>{setColor(c);setQty(1)}} key={c}><span className="color-swatch" style={{backgroundColor:c}} aria-hidden="true"/><span className="color-name">{displayColor(c)}</span></button>})}</div></div>}</div>
