     <div className="cart-item-info cart-item-info-premium"><div className="cart-item-title-row"><b>{x.name}</b><button type="button" className="cart-remove-btn" aria-label={x.name+' কার্ট থেকে সরান'} onClick={()=>changeQty(x.key,0)}><Trash2 size={15}/><span>সরান</span></button></div>
      <small className="cart-variant-label">সাইজ: {x.size||'—'}{x.color?' · রং: '+x.color:''}</small><strong className="cart-item-price">{money(x.price)}</strong>
      <div className="cart-item-controls"><div className="qty-control cart-qty-control"><button type="button" aria-label="পরিমাণ কমান" onClick={()=>changeQty(x.key,x.qty-1)} disabled={x.qty<=1}><Minus size={13}/></button><span>{x.qty}</span><button type="button" aria-label="পরিমাণ বাড়ান" onClick={()=>changeQty(x.key,x.qty+1)}><Plus size={13}/></button></div><b className="cart-line-total">{money(x.price*x.qty)}</b></div>
     </div></article>)}</div>
    <div className="cart-continue-row"><Link to="/shop"><ArrowLeft size={15}/> কেনাকাটা চালিয়ে যান</Link><span>নিরাপদ ও সহজ অর্ডার প্রক্রিয়া</span></div>
